def section(n):
    m = re.search(rf'^## {n}\. .*?$', rec, re.M); nxt = re.search(rf'^## {n+1}\. .*?$', rec, re.M)
    return m.start(), (nxt.start() if nxt else len(rec))
def replace(n, body):
    global rec
    a, b = section(n); head = rec[a:].split('\n', 1)[0]
    rec = rec[:a] + head + '\n\n' + body.rstrip('\n') + '\n\n' + rec[b:]
